fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len() as isize - 1; // Use isize for index calculations

    while left <= right {
        let mid = left + (right - left) / 2; // Calculate mid index

        if v[mid as usize] == k {
            return mid as usize; // Return the index if the target is found
        } else if v[mid as usize] < k {
            left = mid + 1; // Narrow the search to the right half
        } else {
            right = mid - 1; // Narrow the search to the left half
        }
    }

    // Since the problem guarantees that the target appears at least once,
    // we should never reach this point.
    unreachable!()
}